"""Claim extraction adapters."""

from __future__ import annotations

import json
from typing import Protocol

from fastapi import Request

from backend.app.shared.auth.errors import AuthenticationError
from backend.app.shared.auth.models import RawIdentityClaims


class ClaimsExtractor(Protocol):
    """Port used by identity service to read identity material from requests."""

    def has_material(self, request: Request) -> bool:
        """Return True when request contains identity material."""

    def extract(self, request: Request) -> RawIdentityClaims | None:
        """Extract raw identity claims or return None when absent."""


class HeaderClaimsExtractor:
    """Reads JSON claims from a configurable HTTP header."""

    def __init__(self, header_name: str) -> None:
        self._header_name = header_name

    def has_material(self, request: Request) -> bool:
        return bool(request.headers.get(self._header_name))

    def extract(self, request: Request) -> RawIdentityClaims | None:
        raw_value = request.headers.get(self._header_name)
        if not raw_value:
            return None

        try:
            payload = json.loads(raw_value)
        except json.JSONDecodeError as exc:
            raise AuthenticationError("Malformed identity claims header.") from exc

        if not isinstance(payload, dict):
            raise AuthenticationError("Identity claims payload must be a JSON object.")

        return payload
