"""Identity claim normalization."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Iterable

from backend.app.shared.auth.errors import AuthenticationError
from backend.app.shared.auth.models import NormalizedIdentity, RawIdentityClaims
from backend.app.shared.config.auth_config import IdentityClaimMapping


@dataclass(frozen=True)
class IdentityNormalizer:
    """Normalizes OIDC/SAML claims to application DTOs."""

    mapping: IdentityClaimMapping

    def normalize(self, claims: RawIdentityClaims) -> NormalizedIdentity:
        subject = self._extract_scalar(claims, self.mapping.subject_claim, required=True)
        email = self._extract_scalar(claims, self.mapping.email_claim, required=True)
        display_name = self._extract_scalar(
            claims,
            self.mapping.display_name_claim,
            required=False,
        ) or email
        groups = self._extract_groups(claims.get(self.mapping.groups_claim, []))

        return NormalizedIdentity(
            subject=subject,
            email=email,
            display_name=display_name,
            groups=groups,
        )

    @staticmethod
    def _extract_scalar(
        claims: RawIdentityClaims,
        key: str,
        *,
        required: bool,
    ) -> str:
        value = claims.get(key)
        if value is None:
            if required:
                raise AuthenticationError(f"Required identity claim is missing: {key}")
            return ""
        if not isinstance(value, str) or not value.strip():
            raise AuthenticationError(f"Identity claim '{key}' must be a non-empty string.")
        return value.strip()

    @staticmethod
    def _extract_groups(value: Any) -> tuple[str, ...]:
        if isinstance(value, str):
            raw_groups: Iterable[Any] = [part.strip() for part in value.split(",")]
        elif isinstance(value, list):
            raw_groups = value
        elif isinstance(value, tuple):
            raw_groups = value
        else:
            raw_groups = []

        normalized: list[str] = []
        for item in raw_groups:
            if isinstance(item, str):
                candidate = item.strip()
                if candidate and candidate not in normalized:
                    normalized.append(candidate)
        return tuple(normalized)
