"""RBAC mapping service."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RolePermissionResolver:
    """Maps identity groups to roles and permissions."""

    group_role_map: dict[str, tuple[str, ...]]
    role_permissions: dict[str, tuple[str, ...]]
    role_priority: tuple[str, ...]

    def resolve_roles(self, groups: tuple[str, ...]) -> tuple[str, ...]:
        discovered_roles: list[str] = []
        for group in groups:
            for role in self.group_role_map.get(group, ()):
                if role not in discovered_roles:
                    discovered_roles.append(role)

        if not discovered_roles:
            discovered_roles.append("viewer")

        return tuple(
            sorted(
                discovered_roles,
                key=lambda role: self._priority_index(role),
            )
        )

    def resolve_permissions(self, roles: tuple[str, ...]) -> tuple[str, ...]:
        permissions: list[str] = []
        for role in roles:
            for permission in self.role_permissions.get(role, ()):
                if permission not in permissions:
                    permissions.append(permission)
        return tuple(permissions)

    def _priority_index(self, role: str) -> int:
        try:
            return self.role_priority.index(role)
        except ValueError:
            return len(self.role_priority) + 1
