from dataclasses import dataclass, field
import json
import os
from typing import Any


DEFAULT_GROUP_ROLE_MAP: dict[str, tuple[str, ...]] = {
    "zen:operators": ("operator",),
    "zen:validators": ("validator",),
    "zen:search": ("search",),
    "zen:export": ("export",),
    "zen:qa": ("qa",),
    "zen:admins": ("admin",),
}

DEFAULT_ROLE_PERMISSIONS: dict[str, tuple[str, ...]] = {
    "viewer": (),
    "operator": ("upload", "search"),
    "validator": ("validate", "search"),
    "search": ("search",),
    "export": ("export", "search"),
    "qa": ("qa", "search"),
    "admin": ("upload", "validate", "search", "export", "qa"),
}

DEFAULT_ROLE_PRIORITY: tuple[str, ...] = (
    "admin",
    "validator",
    "operator",
    "export",
    "qa",
    "search",
    "viewer",
)


@dataclass(frozen=True)
class IdentityClaimMapping:
    """Protocol-specific claim names mapped into the app identity contract."""

    subject_claim: str = "sub"
    email_claim: str = "email"
    display_name_claim: str = "name"
    groups_claim: str = "groups"


@dataclass(frozen=True)
class AuthSettings:
    """Resolved settings for identity mode, claim extraction and RBAC."""

    auth_mode: str = "mock"
    provider: str = "oidc"
    claims_header_name: str = "x-mock-claims"
    claim_mapping: IdentityClaimMapping = field(default_factory=IdentityClaimMapping)
    group_role_map: dict[str, tuple[str, ...]] = field(
        default_factory=lambda: dict(DEFAULT_GROUP_ROLE_MAP)
    )
    role_permissions: dict[str, tuple[str, ...]] = field(
        default_factory=lambda: dict(DEFAULT_ROLE_PERMISSIONS)
    )
    role_priority: tuple[str, ...] = DEFAULT_ROLE_PRIORITY
    mock_default_claims: dict[str, Any] | None = None
    database_url: str = "sqlite+pysqlite:///./req002_identity.db"

    @classmethod
    def from_env(cls) -> "AuthSettings":
        mapping = IdentityClaimMapping(
            subject_claim=os.getenv("AUTH_SUBJECT_CLAIM", "sub"),
            email_claim=os.getenv("AUTH_EMAIL_CLAIM", "email"),
            display_name_claim=os.getenv("AUTH_DISPLAY_NAME_CLAIM", "name"),
            groups_claim=os.getenv("AUTH_GROUPS_CLAIM", "groups"),
        )

        return cls(
            auth_mode=os.getenv("AUTH_MODE", "mock"),
            provider=os.getenv("AUTH_PROVIDER", "oidc"),
            claims_header_name=os.getenv("AUTH_CLAIMS_HEADER", "x-mock-claims"),
            claim_mapping=mapping,
            group_role_map=_parse_group_role_map(
                os.getenv("AUTH_GROUP_ROLE_MAP"),
                DEFAULT_GROUP_ROLE_MAP,
            ),
            role_permissions=_parse_role_permissions(
                os.getenv("AUTH_ROLE_PERMISSIONS"),
                DEFAULT_ROLE_PERMISSIONS,
            ),
            role_priority=_parse_role_priority(
                os.getenv("AUTH_ROLE_PRIORITY"),
                DEFAULT_ROLE_PRIORITY,
            ),
            mock_default_claims=_parse_json_object(os.getenv("AUTH_MOCK_DEFAULT_CLAIMS")),
            database_url=os.getenv("DATABASE_URL", "sqlite+pysqlite:///./req002_identity.db"),
        )


def _parse_group_role_map(
    raw: str | None,
    default: dict[str, tuple[str, ...]],
) -> dict[str, tuple[str, ...]]:
    payload = _parse_json_object(raw)
    if payload is None:
        return dict(default)

    normalized: dict[str, tuple[str, ...]] = {}
    for group, roles in payload.items():
        if not isinstance(group, str):
            continue
        normalized[group] = _to_str_tuple(roles)
    return normalized or dict(default)


def _parse_role_permissions(
    raw: str | None,
    default: dict[str, tuple[str, ...]],
) -> dict[str, tuple[str, ...]]:
    payload = _parse_json_object(raw)
    if payload is None:
        return dict(default)

    normalized: dict[str, tuple[str, ...]] = {}
    for role, permissions in payload.items():
        if not isinstance(role, str):
            continue
        normalized[role] = _to_str_tuple(permissions)
    return normalized or dict(default)


def _parse_role_priority(raw: str | None, default: tuple[str, ...]) -> tuple[str, ...]:
    if not raw:
        return default

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return default

    if not isinstance(payload, list):
        return default

    values = [item.strip() for item in payload if isinstance(item, str) and item.strip()]
    return tuple(values) if values else default


def _parse_json_object(raw: str | None) -> dict[str, Any] | None:
    if not raw:
        return None

    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        return None

    if not isinstance(payload, dict):
        return None
    return payload


def _to_str_tuple(value: Any) -> tuple[str, ...]:
    if isinstance(value, str):
        return tuple(part.strip() for part in value.split(",") if part.strip())

    if isinstance(value, list):
        return tuple(item.strip() for item in value if isinstance(item, str) and item.strip())

    return ()
