"""Persistence adapters for user upsert on authentication."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Protocol
from uuid import uuid4

from sqlalchemy import Boolean, DateTime, MetaData, String, Table, select
from sqlalchemy.engine import Engine
from sqlalchemy.orm import Session, sessionmaker
from sqlalchemy.sql.schema import Column
from sqlalchemy.dialects.postgresql import insert as pg_insert
from sqlalchemy.dialects.sqlite import insert as sqlite_insert

from backend.app.shared.auth.models import AuthenticatedIdentity, PersistedUser

metadata = MetaData()

USERS_TABLE = Table(
    "users",
    metadata,
    Column("id", String(36), primary_key=True),
    Column("external_subject", String(255), nullable=False, unique=True),
    Column("email", String(320), nullable=False, unique=True),
    Column("display_name", String(255), nullable=False),
    Column("role", String(64), nullable=False, default="viewer"),
    Column("is_active", Boolean, nullable=False, default=True),
    Column("last_login_at", DateTime(timezone=True), nullable=True),
)


class UserIdentityRepository(Protocol):
    """Port used by auth service to persist the authenticated principal."""

    def upsert_from_identity(
        self,
        *,
        identity: AuthenticatedIdentity,
        now: datetime,
    ) -> PersistedUser:
        """Insert or update the user row and return persisted projection."""


def build_session_factory(engine: Engine) -> sessionmaker[Session]:
    """Build SQLAlchemy session factory."""
    return sessionmaker(bind=engine, autoflush=False, future=True)


@dataclass
class SQLAlchemyUserIdentityRepository(UserIdentityRepository):
    """SQLAlchemy repository handling upsert and retrieval by external_subject."""

    session_factory: sessionmaker[Session]
    users_table: Table = USERS_TABLE

    def upsert_from_identity(
        self,
        *,
        identity: AuthenticatedIdentity,
        now: datetime,
    ) -> PersistedUser:
        login_at = now.astimezone(timezone.utc).replace(tzinfo=None)
        role = identity.primary_role or "viewer"

        with self.session_factory.begin() as session:
            stmt = self._build_upsert_statement(
                identity=identity,
                role=role,
                login_at=login_at,
            )
            session.execute(stmt)

            row = session.execute(
                select(self.users_table).where(
                    self.users_table.c.external_subject == identity.subject
                )
            ).mappings().one()

        return PersistedUser(
            id=str(row["id"]),
            external_subject=str(row["external_subject"]),
            email=str(row["email"]),
            display_name=str(row["display_name"]),
            role=str(row["role"]),
            is_active=bool(row["is_active"]),
            last_login_at=row["last_login_at"],
        )

    def _build_upsert_statement(
        self,
        *,
        identity: AuthenticatedIdentity,
        role: str,
        login_at: datetime,
    ):
        payload = {
            "id": str(uuid4()),
            "external_subject": identity.subject,
            "email": identity.email,
            "display_name": identity.display_name,
            "role": role,
            "is_active": True,
            "last_login_at": login_at,
        }

        dialect_name = self.session_factory.kw["bind"].dialect.name
        if dialect_name == "sqlite":
            insert_stmt = sqlite_insert(self.users_table).values(**payload)
            return insert_stmt.on_conflict_do_update(
                index_elements=["external_subject"],
                set_={
                    "email": identity.email,
                    "display_name": identity.display_name,
                    "role": role,
                    "is_active": True,
                    "last_login_at": login_at,
                },
            )

        if dialect_name == "postgresql":
            insert_stmt = pg_insert(self.users_table).values(**payload)
            return insert_stmt.on_conflict_do_update(
                index_elements=["external_subject"],
                set_={
                    "email": identity.email,
                    "display_name": identity.display_name,
                    "role": role,
                    "is_active": True,
                    "last_login_at": login_at,
                },
            )

        # Generic fallback for non-target engines.
        raise RuntimeError(f"Unsupported SQL dialect for upsert: {dialect_name}")
