"""Application service for request authentication and RBAC resolution."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Callable

from fastapi import Request

from backend.app.identity.auth.repository import UserIdentityRepository
from backend.app.shared.auth.errors import AuthenticationError
from backend.app.shared.auth.extractors import ClaimsExtractor
from backend.app.shared.auth.models import (
    AuthenticatedIdentity,
    AuthenticatedSession,
)
from backend.app.shared.auth.normalizer import IdentityNormalizer
from backend.app.shared.config.auth_config import AuthSettings
from backend.app.shared.rbac.service import RolePermissionResolver


def utc_now() -> datetime:
    """Default clock abstraction."""
    return datetime.now(tz=timezone.utc)


@dataclass
class IdentityAccessService:
    """Use-case service orchestrating extraction, normalization, RBAC, and upsert."""

    settings: AuthSettings
    extractor: ClaimsExtractor
    normalizer: IdentityNormalizer
    role_resolver: RolePermissionResolver
    repository: UserIdentityRepository
    clock: Callable[[], datetime] = utc_now

    def has_identity_material(self, request: Request) -> bool:
        if self.extractor.has_material(request):
            return True
        return bool(self.settings.auth_mode == "mock" and self.settings.mock_default_claims)

    def authenticate_request(self, request: Request) -> AuthenticatedSession:
        claims = self.extractor.extract(request)

        if claims is None:
            if self.settings.auth_mode == "mock" and self.settings.mock_default_claims:
                claims = self.settings.mock_default_claims
            else:
                raise AuthenticationError("Authentication material is missing.")

        normalized = self.normalizer.normalize(claims)
        roles = self.role_resolver.resolve_roles(normalized.groups)
        permissions = self.role_resolver.resolve_permissions(roles)

        identity = AuthenticatedIdentity(
            subject=normalized.subject,
            email=normalized.email,
            display_name=normalized.display_name,
            groups=normalized.groups,
            roles=roles,
            permissions=permissions,
        )

        authenticated_at = self.clock()
        persisted_user = self.repository.upsert_from_identity(
            identity=identity,
            now=authenticated_at,
        )

        return AuthenticatedSession(
            identity=identity,
            user=persisted_user,
            authenticated_at=authenticated_at,
        )
