"""FastAPI dependency adapters for auth and RBAC."""

from __future__ import annotations

from collections.abc import Callable

from fastapi import Depends, Request

from backend.app.identity.auth.service import IdentityAccessService
from backend.app.shared.auth.errors import AuthenticationError, AuthorizationError
from backend.app.shared.auth.models import AuthenticatedSession


def get_identity_access_service(request: Request) -> IdentityAccessService:
    """Resolve service instance from app state."""
    return request.app.state.identity_access_service  # type: ignore[no-any-return]


def require_authenticated_session(request: Request) -> AuthenticatedSession:
    """Require middleware-authenticated session."""
    auth_error = getattr(request.state, "authentication_error", None)
    if auth_error:
        raise auth_error

    session = getattr(request.state, "authenticated_session", None)
    if session is None:
        raise AuthenticationError("Missing authenticated identity.")
    return session


def require_permission(permission: str) -> Callable[[AuthenticatedSession], AuthenticatedSession]:
    """Build dependency that enforces one permission."""

    def _enforce(
        session: AuthenticatedSession = Depends(require_authenticated_session),
    ) -> AuthenticatedSession:
        if not session.identity.has_permission(permission):
            raise AuthorizationError(f"Permission '{permission}' is required.")
        return session

    return _enforce
