def test_claim_normalization_for_saml_like_mapping() -> None:
    mapping = IdentityClaimMapping(
        subject_claim="nameid",
        email_claim="mail",
        display_name_claim="displayName",
        groups_claim="memberOf",
    )
    normalizer = IdentityNormalizer(mapping)
    normalized = normalizer.normalize(
        {
            "nameid": "saml-subject",
            "mail": "saml@example.test",
            "displayName": "SAML User",
            "memberOf": "zen:validators,zen:qa",
